func TestNewAccumulator(t *testing.T) {
	tests := []struct {
		name    string
		config  AccumulationConfig
		wantErr bool
	}{
		{
			name: "count without filter",
			config: AccumulationConfig{
				Name:      "total_count",
				Operation: "count",
			},
			wantErr: false,
		},
		{
			name: "count with filter",
			config: AccumulationConfig{
				Name:      "suspended_count",
				Operation: "count",
				Filter:    "is_suspended == true",
			},
			wantErr: false,
		},
		{
			name: "sum with field",
			config: AccumulationConfig{
				Name:      "revenue_total",
				Operation: "sum",
				Field:     "total_grand_amount",
			},
			wantErr: false,
		},
		{
			name: "invalid filter",
			config: AccumulationConfig{
				Name:      "bad_count",
				Operation: "count",
				Filter:    "field without operator",
			},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := NewAccumulator(tt.config)
			if (err != nil) != tt.wantErr {
				t.Errorf("NewAccumulator() error = %v, wantErr %v", err, tt.wantErr)
				return
			}

			if !tt.wantErr && got == nil {
				t.Error("NewAccumulator() returned nil, want non-nil")
			}
		})
	}
}

func TestAccumulatorCount(t *testing.T) {
	config := AccumulationConfig{
		Name:      "total_count",
		Operation: "count",
	}

	acc, err := NewAccumulator(config)
	if err != nil {
		t.Fatalf("NewAccumulator() error = %v", err)
	}

	// Update with 3 records
	records := []map[string]interface{}{
		{"id": 1},
		{"id": 2},
		{"id": 3},
	}

	for _, record := range records {
		if err := acc.Update(record); err != nil {
			t.Fatalf("Update() error = %v", err)
		}
	}

	result, err := acc.GetResult()
	if err != nil {
		t.Fatalf("GetResult() error = %v", err)
	}

	if result != 3 {
		t.Errorf("GetResult() = %v, want 3", result)
	}
}

