func TestAccumulatorReset(t *testing.T) {
	config := AccumulationConfig{
		Name:      "count",
		Operation: "count",
	}

	acc, err := NewAccumulator(config)
	if err != nil {
		t.Fatalf("NewAccumulator() error = %v", err)
	}

	// Add some records
	for i := 0; i < 5; i++ {
		if err := acc.Update(map[string]interface{}{"id": i}); err != nil {
			t.Fatalf("Update() error = %v", err)
		}
	}

	// Reset
	acc.Reset()

	// Verify reset
	if acc.Count != 0 {
		t.Errorf("After reset, Count = %d, want 0", acc.Count)
	}
	if acc.Sum != 0.0 {
		t.Errorf("After reset, Sum = %f, want 0.0", acc.Sum)
	}
	if !math.IsInf(acc.Min, 1) {
		t.Errorf("After reset, Min = %f, want +Inf", acc.Min)
	}
	if !math.IsInf(acc.Max, -1) {
		t.Errorf("After reset, Max = %f, want -Inf", acc.Max)
	}
}
